export function wfAskType(): L.Type<WfAsk>;

/** What the runtime does. */
export type RunAct =
  | {
      /** Nothing. */
      readonly kind: "none";
    }
  | {
      /** Admit nothing new, and close the run's live feeds. */
      readonly kind: "stop";
    }
  | {
      /** Cancel every live request, attributed to the user, and start the grace. */
      readonly kind: "cancel";
    }
  | {
      /** End what is left at once: the grace is over, or was cut short. */
      readonly kind: "kill";
    }
  | {
      /** The run is over: report it. */
      readonly kind: "finish";
    }
;
/** The descriptor of CapDAG.Run.Control.RunAct: how its values cross the boundary. */
export function runActType(): L.Type<RunAct>;

/** The values a key may hold when it is there. */
export type Values =
  | {
      /** Exactly these values. */
      readonly kind: "oneOf";
      /** The field `vs` of Lean's TaggedUrn.Values.oneOf. */
      readonly vs: Array<string>;
    }
  | {
      /** Every value but these. */
      readonly kind: "noneOf";
      /** The field `vs` of Lean's TaggedUrn.Values.noneOf. */
      readonly vs: Array<string>;
    }
;
/** The descriptor of TaggedUrn.Values: how its values cross the boundary. */
export function valuesType(): L.Type<Values>;

